void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npanels = (n + NR - 1) / NR;
    float *Bp = (float *)alloc64((size_t)npanels * NR * KC * sizeof(float));
    int nib = (n + MC - 1) / MC;
    int njb = (n + NCG - 1) / NCG;
    int nitems = nib * njb;

