                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCG;
                int nc = n - jc < NCG ? n - jc : NCG;

                /* pack A[ic:ic+mc, pc:pc+kc] into MR-row panels */
                for (int ir = 0; ir < mc; ir += MR) {
                    float *dst = Ap + (size_t)(ir / MR) * kc * MR;
                    int mr = mc - ir < MR ? mc - ir : MR;
